insert into public.mocktest_listening (level, data)
values (
  'B2',
  '{"text":"Good morning. Today I would like to discuss the topic of remote work, which has become increasingly common since the global pandemic of 2020. Many companies have adopted flexible working policies, allowing employees to work from home for some or all of the week. Research has shown that remote workers often report higher levels of job satisfaction and productivity. However, the shift to remote work also presents significant challenges. Employees frequently struggle with feelings of isolation and find it difficult to separate their professional and personal lives when both take place in the same environment. Communication can also become less effective without face-to-face interaction. Companies that have successfully implemented remote work policies typically invest in regular virtual team-building activities and provide employees with the technology and resources they need to work effectively from home. The consensus among experts is that a hybrid model — combining remote work with some office time — offers the best balance between flexibility and collaboration.","mcq":[{"q":"According to the lecture, what has been observed about remote workers?","opts":["They are less satisfied with their jobs.","They report higher job satisfaction and productivity.","They prefer to return to the office full-time.","They earn less money than office workers."],"ans":1},{"q":"What challenge of remote work does the speaker mention?","opts":["Longer working hours","Difficulty separating work and personal life","Higher commuting costs","Limited internet access"],"ans":1},{"q":"What is a recommended strategy for successful remote work implementation?","opts":["Requiring employees to work longer hours","Investing in virtual team-building activities","Reducing communication between team members","Eliminating all meetings"],"ans":1},{"q":"What does the speaker say about the hybrid model?","opts":["It is not recommended by experts.","It is less effective than full remote work.","It offers the best balance of flexibility and collaboration.","It only works for large companies."],"ans":2},{"q":"What problem with remote communication does the speaker identify?","opts":["Video calls are too expensive.","Communication can be less effective without face-to-face interaction.","Employees refuse to use video conferencing.","Written communication has replaced all verbal communication."],"ans":1},{"q":"According to the lecture, what did the 2020 pandemic do?","opts":["It ended the practice of remote work.","It made remote work increasingly common.","It had no effect on working patterns.","It reduced the number of home workers."],"ans":1},{"q":"What feeling do remote workers sometimes experience?","opts":["Excitement about office life","Isolation","Indifference towards their work","Over-confidence"],"ans":1},{"q":"What should companies provide remote employees according to the speaker?","opts":["Office furniture","Technology and resources for effective home work","Transportation allowances","Meal vouchers"],"ans":1}]}'::jsonb
);

